<script setup>
import {computed} from 'vue';import {simulateBoundaries} from '../sim/models/boundary.mjs';import {useLabSession} from '../sim/session.mjs';
const props=defineProps({focus:{type:String,default:'layout'}});const s=useLabSession('boundaries');const r=computed(()=>simulateBoundaries(s));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>部署方式</span><div class="sim-segment"><button :aria-pressed="s.layout==='modular'" @click="s.layout='modular'">單一 App／模組分責任</button><button :aria-pressed="s.layout==='services'" @click="s.layout='services'">多個 Services</button></div></div><div v-if="props.focus!=='layout'"><span>改一條 boundary</span><div class="sim-segment"><button :disabled="s.layout==='services'" :aria-pressed="s.layout==='services'||s.movePayment" @click="s.movePayment=!s.movePayment">{{s.layout==='services'?'Payment 已隨多 Services 獨立':'Payment 獨立部署'}}</button><button v-if="props.focus==='contract'||props.focus==='transfer'" :aria-pressed="s.directDbWrite" @click="s.directDbWrite=!s.directDbWrite">Payment 直接寫 Order DB</button><button v-if="props.focus==='trust'||props.focus==='transfer'" :aria-pressed="s.clientAuthOnly" @click="s.clientAuthOnly=!s.clientAuthOnly">只靠前端授權</button></div></div></div><div class="boundary-system"><div class="boundary-zone"><b>Order</b><span>建立／修改訂單</span></div><div class="boundary-zone"><b>Inventory</b><span>庫存規則</span></div><div :class="['boundary-zone',{'is-separated':r.paymentBoundary}]"><b>Payment</b><span>{{r.paymentBoundary?'跨 boundary':'同一 deployment unit'}}</span></div><div class="boundary-zone"><b>Shipping</b><span>出貨結果</span></div></div><div class="sim-metrics"><div><span>部署單位</span><strong>{{r.deployUnits}}</strong></div><div><span>跨界 calls</span><strong>{{r.crossBoundaryCalls}}</strong></div><div :class="{'is-bad':r.sharedWrites>0}"><span>共享直接寫入</span><strong>{{r.sharedWrites}}</strong></div><div :class="{'is-bad':r.trustCrossings>0&&s.clientAuthOnly}"><span>Trust crossings</span><strong>{{r.trustCrossings}}</strong></div></div><div class="sim-consequence"><strong>切 boundary 不是免費的</strong><p v-if="r.risks.length">{{r.risks.join('；')}}。</p><p v-else>目前責任仍可在單一 deployment unit 內清楚分開。只有出現獨立部署、擴展、安全或故障隔離需求時，才需要為跨服務成本付費。</p></div></section></template>